-- Authentication tables (ADR 0001). Better Auth DDL generated by scripts/print-auth-ddl.ts, reviewed, plus
-- our constraints. Only belgobeton_auth can touch them; belgobeton_app gets nothing (credentials stay out of reach).
-- They are not audited by the capture trigger (the library writes outside withRlsContext); auth actions are
-- recorded as service events instead (documented exception, like audit_event).

CREATE TABLE "user" (
  "id" text NOT NULL PRIMARY KEY CHECK ("id" ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'),
  "name" text NOT NULL,
  "email" text NOT NULL UNIQUE CHECK ("email" = lower("email")),
  "emailVerified" boolean NOT NULL,
  "image" text,
  "createdAt" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updatedAt" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "twoFactorEnabled" boolean,
  "role" text NOT NULL CHECK ("role" IN ('owner', 'partner', 'office', 'plant')),
  "locale" text NOT NULL CHECK ("locale" IN ('fr', 'ar')),
  "status" text NOT NULL CHECK ("status" IN ('active', 'disabled'))
);
--> statement-breakpoint
-- At most one owner (the CLI refuses a second one; this makes it a database rule too).
CREATE UNIQUE INDEX user_single_owner ON "user" (("role")) WHERE "role" = 'owner';
--> statement-breakpoint
CREATE TABLE "session" (
  "id" text NOT NULL PRIMARY KEY,
  "expiresAt" timestamptz NOT NULL,
  "token" text NOT NULL UNIQUE,
  "createdAt" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updatedAt" timestamptz NOT NULL,
  "ipAddress" text CHECK ("ipAddress" IS NULL),   -- IP tracking disabled: raw IPs are never stored
  "userAgent" text,
  "userId" text NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  "twoFactorAt" timestamptz
);
--> statement-breakpoint
CREATE TABLE "account" (
  "id" text NOT NULL PRIMARY KEY,
  "accountId" text NOT NULL,
  "providerId" text NOT NULL CHECK ("providerId" = 'credential'),
  "userId" text NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  "accessToken" text,
  "refreshToken" text,
  "idToken" text,
  "accessTokenExpiresAt" timestamptz,
  "refreshTokenExpiresAt" timestamptz,
  "scope" text,
  "password" text CHECK ("password" IS NULL OR "password" LIKE '$argon2id$%'),
  "createdAt" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updatedAt" timestamptz NOT NULL
);
--> statement-breakpoint
CREATE TABLE "verification" (
  "id" text NOT NULL PRIMARY KEY,
  "identifier" text NOT NULL,
  "value" text NOT NULL,
  "expiresAt" timestamptz NOT NULL,
  "createdAt" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updatedAt" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL
);
--> statement-breakpoint
CREATE TABLE "twoFactor" (
  "id" text NOT NULL PRIMARY KEY,
  "secret" text NOT NULL,
  "backupCodes" text NOT NULL CHECK ("backupCodes" LIKE 'v1.%'),  -- AES-GCM with RECOVERY_CODES_KEY, never plain
  "userId" text NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  "verified" boolean,
  "failedVerificationCount" integer,
  "lockedUntil" timestamptz
);
--> statement-breakpoint
CREATE INDEX "session_userId_idx" ON "session" ("userId");
--> statement-breakpoint
CREATE INDEX "account_userId_idx" ON "account" ("userId");
--> statement-breakpoint
CREATE INDEX "verification_identifier_idx" ON "verification" ("identifier");
--> statement-breakpoint
CREATE INDEX "twoFactor_secret_idx" ON "twoFactor" ("secret");
--> statement-breakpoint
CREATE INDEX "twoFactor_userId_idx" ON "twoFactor" ("userId");
--> statement-breakpoint

-- Login lockout (SPEC §5): keyed hashes only, never the typed identifier or the IP.
CREATE TABLE login_attempt (
  id              bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  at              timestamptz NOT NULL,
  identifier_hmac bytea NOT NULL CHECK (octet_length(identifier_hmac) = 32),
  ip_hmac         bytea NOT NULL CHECK (octet_length(ip_hmac) = 32),
  success         boolean NOT NULL
);
--> statement-breakpoint
CREATE INDEX login_attempt_identifier_idx ON login_attempt (identifier_hmac, at);
--> statement-breakpoint
CREATE INDEX login_attempt_ip_idx ON login_attempt (ip_hmac, at);
--> statement-breakpoint
-- TOTP replay protection: the last accepted 30-second time-step per user.
CREATE TABLE totp_used_step (
  user_id   text PRIMARY KEY REFERENCES "user" ("id"),
  last_step bigint NOT NULL
);
--> statement-breakpoint
REVOKE ALL ON "user", "session", "account", "verification", "twoFactor", login_attempt, totp_used_step FROM PUBLIC;
--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON "user", "account" TO belgobeton_auth;
--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON "session", "verification", "twoFactor" TO belgobeton_auth;
--> statement-breakpoint
GRANT SELECT, INSERT ON login_attempt TO belgobeton_auth;
--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON totp_used_step TO belgobeton_auth;
--> statement-breakpoint

-- Audit: auth service events and the anonymous actor kind (failed logins, CP2).
ALTER TABLE public.audit_event DROP CONSTRAINT audit_event_action_check;
--> statement-breakpoint
ALTER TABLE public.audit_event ADD CONSTRAINT audit_event_action_check CHECK (action IN (
  'insert', 'update', 'reverse', 'archive',
  'login', 'login_failed', 'logout', 'account_locked', 'permission_denied', 'export',
  'user_created', 'two_factor_enrolled', 'recovery_codes_generated', 'recovery_code_used', 'step_up',
  'session_revoked', 'ai_proposal', 'ai_confirmation', 'telegram_link', 'clock_advance'));
--> statement-breakpoint
ALTER TABLE public.audit_event DROP CONSTRAINT audit_event_actor_kind_check;
--> statement-breakpoint
ALTER TABLE public.audit_event ADD CONSTRAINT audit_event_actor_kind_check
  CHECK (actor_kind IN ('user', 'system', 'anonymous', 'ai_confirmed'));
--> statement-breakpoint
CREATE OR REPLACE FUNCTION audit.append(
  p_action text, p_table text, p_row_id text, p_before jsonb, p_after jsonb, p_reason text
) RETURNS bigint LANGUAGE plpgsql SET search_path = '' AS $$
DECLARE
  v_id   bigint;
  v_at   timestamptz;
  v_kind text := CASE ctx.role() WHEN 'system' THEN 'system' WHEN 'anonymous' THEN 'anonymous' ELSE 'user' END;
  v_prev bytea;
  v_hash bytea;
BEGIN
  IF ctx.user_id() IS NULL THEN
    RAISE EXCEPTION 'audit: app.user_id is not set; writes need withRlsContext()'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'audit: writes must run in READ COMMITTED (got %)', current_setting('transaction_isolation');
  END IF;

  PERFORM pg_advisory_xact_lock(7041001);
  SELECT hash INTO v_prev FROM public.audit_event ORDER BY id DESC LIMIT 1;
  v_id := nextval(pg_get_serial_sequence('public.audit_event', 'id'));
  v_at := clock_timestamp();
  v_hash := sha256(coalesce(v_prev, ''::bytea) || convert_to(audit.canonical_parts(
    v_id, v_at, ctx.sim_at(), ctx.user_id(), v_kind, ctx.request_id(),
    p_table, p_row_id, p_action, p_before, p_after, p_reason), 'UTF8'));

  INSERT INTO public.audit_event
    (id, at, sim_at, actor_user_id, actor_kind, request_id, table_name, row_id, action, before, after, reason, prev_hash, hash)
  OVERRIDING SYSTEM VALUE VALUES
    (v_id, v_at, ctx.sim_at(), ctx.user_id(), v_kind, ctx.request_id(),
     p_table, p_row_id, p_action, p_before, p_after, p_reason, v_prev, v_hash);
  RETURN v_id;
END $$;
